"use strict";
import { useState } from "react";
import { Flex, Text, Popover } from "ui/src";
import { Lock } from "react-feather";
import { RotatableChevron } from "ui/src/components/icons/RotatableChevron";
import { DropdownMenuSheetItem } from "ui/src/components/dropdownMenuSheet/DropdownMenuSheetItem";
import { AnimatedPopover } from "ui/src/components/popover/AnimatedPopover";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { addPendingVote, removePendingVote, selectPendingVotes, setSelectedLock, selectSelectedLock } from "state/voting/slice";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useVotingStatus } from "hooks/useVotingStatus";
import { formatLockAmount } from "utils/lockCalculations";
export default function PopoverAllVotes({ gauge }) {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dispatch = useAppDispatch();
  const account = useAccount();
  const pendingVotes = useAppSelector(selectPendingVotes);
  const selectedLock = useAppSelector(selectSelectedLock);
  const { data: userLocks } = useVeABXUserLocks(account.address);
  if (!gauge) {
    return <Flex row gap="$gap4" alignItems="center">
        <Text variant="body3" color="$neutral3">
          No gauge
        </Text>
      </Flex>;
  }
  const isSelected = pendingVotes.some((vote) => vote.poolAddress === gauge.pool);
  const userOwnedLocks = userLocks?.filter((lock) => {
    const isOwner = lock.owner.toLowerCase() === account.address?.toLowerCase();
    const isNotExpired = lock.permanent || parseInt(lock.lockEnd) * 1e3 > Date.now();
    return isOwner && isNotExpired;
  }) || [];
  const { lockStatuses } = useVotingStatus(userOwnedLocks);
  const availableLocks = userOwnedLocks.filter((lock) => {
    const lockStatus = lockStatuses.find((status) => status.tokenId === lock.id);
    const hasVoted = lockStatus?.hasVoted || false;
    return !hasVoted;
  });
  const handleLockSelect = (lockId) => {
    const lock = availableLocks.find((l) => l.id === lockId);
    if (lock) {
      dispatch(setSelectedLock(lock));
      dispatch(addPendingVote({
        poolAddress: gauge.pool,
        poolId: gauge.id,
        weight: 1,
        pool: gauge
      }));
    }
    setIsDropdownOpen(false);
  };
  const handleToggleSelect = () => {
    if (isSelected) {
      dispatch(removePendingVote(gauge.pool));
    } else if (availableLocks.length === 1) {
      handleLockSelect(availableLocks[0].id);
    } else if (availableLocks.length > 1) {
      setIsDropdownOpen(true);
    }
  };
  if (availableLocks.length === 0) {
    const hasLocks = userOwnedLocks.length > 0;
    const allVoted = hasLocks && lockStatuses.every((status) => status.hasVoted);
    return <Flex row gap="$gap4" alignItems="center">
        <Text variant="body3" color="$neutral3">
          {allVoted ? "All locks voted" : "No locks"}
        </Text>
      </Flex>;
  }
  return <Popover placement="bottom-start" allowFlip stayInFrame>
      <Popover.Trigger>
        <Flex
    row
    gap="$gap4"
    alignItems="center"
    cursor="pointer"
    onPress={handleToggleSelect}
    py="$spacing4"
    px="$spacing8"
    borderRadius="$rounded8"
    backgroundColor={isSelected ? "$accent1" : "$surface2"}
    hoverStyle={{
      backgroundColor: isSelected ? "$accent1Hovered" : "$surface2Hovered"
    }}
  >
          <Text
    variant="body3"
    color={isSelected ? "$surface1" : "$neutral1"}
  >
            {isSelected ? "Selected" : "Select"}
          </Text>
          {!isSelected && availableLocks.length > 1 && <RotatableChevron
    direction={isDropdownOpen ? "up" : "down"}
    width={16}
    height={16}
    color={isSelected ? "$surface1" : "$neutral2"}
  />}
        </Flex>
      </Popover.Trigger>
      
      {!isSelected && availableLocks.length > 1 && <AnimatedPopover isOpen={isDropdownOpen} marginTop="$spacing4">
          <Flex gap="$gap4" pb={"$spacing20"}>
            <Text variant="subheading2" color="$neutral1" px="$spacing12" pt="$spacing8">
              Select Lock
            </Text>
            {availableLocks.map((lock) => {
    const formatAmount = (amount) => {
      const num = parseFloat(formatLockAmount(amount));
      if (num < 1e3) return num.toFixed(2);
      if (num < 1e6) return (num / 1e3).toFixed(2) + "K";
      return (num / 1e6).toFixed(2) + "M";
    };
    const formatVotingPower = (votingPower) => {
      const num = parseFloat(formatLockAmount(votingPower));
      if (num < 1e3) return num.toFixed(2);
      if (num < 1e6) return (num / 1e3).toFixed(2) + "K";
      return (num / 1e6).toFixed(2) + "M";
    };
    const lockLabel = `Lock #${lock.id}${lock.permanent ? " \u267E\uFE0F" : ""}`;
    const amountInfo = `${formatAmount(lock.amount)} ABX \u2022 ${formatVotingPower(lock.votingPower)} veABX`;
    return <DropdownMenuSheetItem
      key={lock.id}
      label={`${lockLabel} \u2022 ${amountInfo}`}
      variant="medium"
      onPress={() => handleLockSelect(lock.id)}
      isSelected={selectedLock?.id === lock.id}
      icon={<Lock size={14} color="#888" />}
    />;
  })}
          </Flex>
        </AnimatedPopover>}
    </Popover>;
}
