"use strict";
import { Flex, Separator, Text, styled as UiStyled } from "ui/src";
import { useVotingRoundData, VotingRoundUtils } from "../../../hooks/useVotingRoundData";
export default function VotingRound() {
  const {
    daysRemaining,
    hoursRemaining,
    isVotingPeriod,
    totalVotingPowerFormatted,
    totalFees,
    totalIncentives,
    totalRewards,
    newEmissions,
    isLoading
  } = useVotingRoundData();
  const TextTypeOne = UiStyled(Text, {
    variant: "body3",
    color: "$neutral2",
    fontSize: "$mdall"
  });
  const TextTypeTwo = UiStyled(TextTypeOne, {
    color: "$neutral3"
  });
  return <Flex
    row
    borderStyle="solid"
    flexDirection="column"
    borderWidth={1}
    borderColor="$surface2Hovered"
    borderRadius={"$rounded12"}
    p={"$spacing16"}
  >
      <Flex
    className="top"
    row
    $lg={{ flexDirection: "column" }}
    justifyContent="space-between"
    width={"100%"}
    gap={"$spacing16"}
  >
        <Flex className="left" row gap={"$spacing8"} alignItems="center">
          <Text variant={"body3"}>Current voting round</Text>
          <Text
    variant={"body3"}
    px={"$spacing16"}
    py={"$spacing6"}
    borderRadius={"$roundedFull"}
    backgroundColor={isVotingPeriod ? "$surface2Hovered" : "$surface2"}
    color={isVotingPeriod ? "$white" : "$neutral1"}
    textAlign="center"
    $lg={{ variant: "body4", px: "$spacing12", py: "$spacing4" }}
  >
            {isLoading ? "..." : VotingRoundUtils.getTimeRemainingText(daysRemaining, hoursRemaining)}
          </Text>
        </Flex>

        <TextTypeTwo maxWidth={"30rem"} variant={"body3"} color={"$neutral3"}>
          Voters earn a share of transaction fees and incentives for helping govern how
          emissions are distributed.
        </TextTypeTwo>
      </Flex>

      <Separator my={"$spacing16"} width={"100%"} borderColor={"$surface2Hovered"} />

      <Flex
    className="bottom"
    row
    $lg={{ flexDirection: "column" }}
    justifyContent="space-between"
    width={"100%"}
    gap={"$spacing16"}
  >
        <Flex className="left" row gap={"$spacing8"}>
          <TextTypeTwo>Total voting power this epoch:</TextTypeTwo>
          <TextTypeOne>
            {isLoading ? "..." : VotingRoundUtils.formatLargeNumber(totalVotingPowerFormatted)}
          </TextTypeOne>
        </Flex>

        <Flex
    className="right"
    maxWidth={"30rem"}
    width={"100%"}
    flexWrap="wrap"
    row
    alignItems="center"
    gap={"$spacing8"}
  >
          {
    /* total fees */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>Total fees:</TextTypeTwo>
            <TextTypeOne>
              {isLoading ? "..." : `~${VotingRoundUtils.formatUSDValue(totalFees)}`}
            </TextTypeOne>
          </Flex>
          {
    /* Total Incentives: */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>Total incentives:</TextTypeTwo>
            <TextTypeOne>
              {isLoading ? "..." : `~${VotingRoundUtils.formatUSDValue(totalIncentives)}`}
            </TextTypeOne>
          </Flex>
          {
    /*  */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>Total rewards:</TextTypeTwo>
            <TextTypeOne>
              {isLoading ? "..." : `~${VotingRoundUtils.formatUSDValue(totalRewards)}`}
            </TextTypeOne>
          </Flex>
          {
    /*  */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>New emissions:</TextTypeTwo>
            <TextTypeOne>
              {isLoading ? "..." : VotingRoundUtils.formatLargeNumber(newEmissions)}
            </TextTypeOne>
          </Flex>
        </Flex>
      </Flex>
    </Flex>;
}
